    if (/^create\b/i.test(s)) return hintFor('To register a new product type: create name quantity unit reorder-level, for example: create Bottled Water 100 bottle 20\n\nSend help to see all commands.');
    const looksLikeCommand = /^(add|remove|set|create)\b/i.test(s);
    return [{ json: Object.assign(base, { route: 'reply', reply_text: (looksLikeCommand ? 'I could not read that command.\n\n' : '') + help }) }];
  }
  return [{ json: Object.assign(base, { route: 'single', dry_run: dry, is_single: true, rows: [row], file_name: 'Chat command', update_id: String(updateId) }) }];
